(async () => {
  /**
     * UI
     */
  const html = `
    <div class="flex flex-col dataviz-block">
        <h5 style="padding-left:0.5rem">Population / Gross domestic product / Greenhouse Gases - change in % since 1990</h5>
        <div id="line-change-chart" class="grow dataviz-chart"></div>
    </div>`;
  $(this).html(html);

  /**
   * Parameters
   */
  const apiBaseUrl = ''https://dash.unccd.unepgrid.ch/api'';
  const country = ''[grid-dataviz:iso3cc]'';
  const colors = [
    "#4f9e45",
    "#efb960",
    "#cc7c4b",
    "#077cc0",
    "#bcd231"
  ];

  /**
   * Queries to retrieve data from Superset
   */
  const queryContextTrends = {
    datasource: {
      id: 13,
      type: "table"
    },
    force: false,
    queries: [{
      time_range: "No filter",
      filters: [{
        col: "indicator_uid",
        op: "==",
        val: "1834"
      },
      {
        col: "code_iso3",
        op: "==",
        val: `${country}`
      }
      ],
      extras: {
        time_grain_sqla: "P1D",
        having: "",
        having_druid: []
      },
      applied_time_extras: {},
      annotation_layers: [],
      groupby: [],
      columns: [
        "indicator_name_label",
        "date_start",
        "indicator_value",
        "pop",
        "gdp"
      ],
      metrics: [],
      order_desc: true,
      orderby: [],
      row_limit: 10000,
      timeseries_limit: 0,
      url_params: {}
    }],
    result_format: "json",
    result_type: "full"
  };

  /**
   * Fetch all data
   */
  const dataTrends = await fetchData(apiBaseUrl, queryContextTrends);

  /**
   * Generate series
   */
  const seriesTrends = initSeriesTrends(dataTrends);

  /**
   * Generate charts
   */
  const chartTrends = initChartTrends(''line-change-chart'', seriesTrends, colors);

  $(window).resize(function () {
    chartTrends.reflow();
  });

  /*
   * Utility functions
   */
  async function fetchData(apiBaseUrl, queryContext) {
    const response = await fetch(`${apiBaseUrl}/v1/chart/data`, {
      method: ''POST'',
      headers: {
        ''accept'': ''application/json'',
        ''Content-Type'': ''application/json''
      },
      body: JSON.stringify(queryContext)
    });
    const data = await response.json();
    return data.result[0].data;
  }

  function initSeriesTrends(data) {
    let sortedData = data.sort((a, b) => a.date_start - b.date_start);

    let ghg = [],
      gdp = [],
      pop = [],
      years = [];

    sortedData.forEach(d => {
      ghg.push(d.indicator_value);
      gdp.push(d.gdp);
      pop.push(d.pop);

      let date = new Date(d.date_start);
      let year = date.getUTCFullYear();
      years.push(year);
    });

    const isNotNull = (element) => (element) != null;

    const ghgFirstValueIndex = ghg.findIndex(isNotNull);
    const gdpFirstValueIndex = gdp.findIndex(isNotNull);
    const popFirstValueIndex = pop.findIndex(isNotNull);

    let series = {
      ghg: yearlyIncrease(ghg, ghgFirstValueIndex),
      gdp: yearlyIncrease(gdp, gdpFirstValueIndex),
      pop: yearlyIncrease(pop, popFirstValueIndex),
      years: years
    };
    return series;
  }

  function yearlyIncrease(data, firstValue) {
    let length = data.length;
    let yearlyIncrease = [];

    for (let i = 0; i < length; i++) {
      if (i < firstValue) {
        yearlyIncrease.push(null);
      } else {
        if (data[i]) {
          let value = (((data[i] - data[firstValue]) / data[firstValue]) * 100);
          yearlyIncrease.push(value);
        } else {
          yearlyIncrease.push(null);
        }
      }
    }
    return yearlyIncrease;
  }

  function initChartTrends(container, series, colors) {
    const chart = Highcharts.chart(container, {
      chart: {
        type: ''area'',
        margin: [10, 10, 45, 40],
        style: {
          fontFamily: ''Montserrat, sans-serif''
        }
      },
      colors: colors,
      title: {
        text: ''''
      },
      xAxis: {
        categories: series.years,
        labels: {
          style: {
            fontSize: ''0.7em'',
            color: "#999999"
          }
        },
        tickPositions: [0, (series.years.length - 1)],
        gridLineWidth: 0,
        minorGridLineWidth: 0,
        lineWidth: 0
      },
      yAxis: {
        title: {
          text: undefined
        },
        labels: {
          style: {
            fontSize: ''0.7em'',
            color: "#999999"
          }
        },
        gridLineWidth: 0,
        minorGridLineWidth: 0,
        lineWidth: 1
      },
      legend: {
        layout: ''vertical'',
        align: ''left'',
        verticalAlign: ''top'',
        floating: true,
        borderWidth: 0.5,
        borderRadius: 5,
        itemStyle: {
            fontSize: ''0.8em'',
            fontWeight: ''normal''
        },
        x: 65,
        y: 25
      },
      tooltip: {
        shared: true,
        valueDecimals: 2,
        valueSuffix: '' %'',
        useHTML: true
      },
      credits: {
        text: ''Credits: Climate Watch, UN COMTRADE International Trade Statistics Database, World Population Prospects'',
        href: '''',
        style: {
          fontSize: "0.7em"
        },
        position:
        {
          align: "left",
          verticalAlign: "bottom",
          x: 10,
          y: -10
        }
      },
      plotOptions: {
        line: {
          marker: {
            enabled: false
          },
          lineWidth: 2,
          states: {
            hover: {
              enabled: false
            }
          },
          threshold: null
        }
      },
      series: [{
        name: ''GHG'',
        data: series.ghg,
        lineWidth: 2,
        color: colors[0],
        marker: {
          enabled: false
        },
        fillColor: {
          linearGradient: {
            x1: 0,
            x2: 0,
            y1: 0,
            y2: 1
          },
          stops: [
            [0, Highcharts.color(colors[0]).setOpacity(0.5).get(''rgba'')],
            [1, Highcharts.color(colors[0]).setOpacity(0).get(''rgba'')]
          ]
        }
      }, {
        name: ''GDP'',
        data: series.gdp,
        lineWidth: 2,
        color: colors[1],
        marker: {
          enabled: false
        },
        fillColor: {
          linearGradient: {
            x1: 0,
            x2: 0,
            y1: 0,
            y2: 1
          },
          stops: [
            [0, Highcharts.color(colors[1]).setOpacity(0.5).get(''rgba'')],
            [1, Highcharts.color(colors[1]).setOpacity(0).get(''rgba'')]
          ]
        }
      }, {
        name: ''Population'',
        data: series.pop,
        lineWidth: 2,
        color: colors[2],
        marker: {
          enabled: false
        },
        fillColor: {
          linearGradient: {
            x1: 0,
            x2: 0,
            y1: 0,
            y2: 1
          },
          stops: [
            [0, Highcharts.color(colors[2]).setOpacity(0.5).get(''rgba'')],
            [1, Highcharts.color(colors[2]).setOpacity(0).get(''rgba'')]
          ]
        }
      }]
    });
    return chart;
  }
})();

