        visible: false
      },
      yAxis: {
        visible: false
      },
      legend: {
        enabled: false
      },
      tooltip: {
        shared: true,
        valueDecimals: 2,
        valueSuffix: '' %'',
        useHTML: true
      },
      credits: {
        enabled: false
      },
      plotOptions: {
        line: {
          marker: {
            enabled: false
          },
          lineWidth: 2,
          states: {
            hover: {
              enabled: false
            }
          },
          threshold: null
        }
      },
      series: [{
        name: ''GHG'',
        data: series.ghg,
        lineWidth: 2,
        color: colors[0],
