    const country = "[grid-dataviz:iso3cc]";
    const indicators = [
      "Wet mass movement",
      "Drought",
      "Wildfire",
      "Flood"
    ]
    const colors = [
      "#4f9e45",
      "#efb960",
      "#cc7c4b",
      "#077cc0",
      "#bcd231"
    ];
  
    /**
     * Queries to retrieve data from Superset
     */
    const queryContext = {
      datasource: {
