// Build party status table
(async () => {
  const response = await fetch(`${baseJsonUrl}/infomea_ratifications_${iso3cc}.json`);
  const json = await response.json();
  if (json?.data[0]) {
    // const data = json?.data;
    const data = json?.data.sort((a, b) => b.ratification_date.localeCompare(a.ratification_date));
    const $table = $(''<table>'');

    // build table header
    $table.append(`
      <thead>
        <tr class="whitespace-nowrap">
          <th class="sticky bg-white">Treaty</th>
          <th class="sticky bg-white">Signature</th>
          <th class="sticky bg-white">Ratification</th>
          <th class="sticky bg-white">Party status</th>
        </tr>
      </thead>
    `);

    // build table body
    const $body = $(''<tbody style=" font-size: 15px;">'');
    for (const [keyr, row] of Object.entries(data)) {
      $body.append(`
