        labels: {
          style: {
            fontSize: ''0.7em'',
            color: "#999999"
          }
        },
        gridLineWidth: 0,
        minorGridLineWidth: 0,
        lineWidth: 1
      }, {
        title: {
          text: ''Use per area of cropland (kg/ha)'',
          style: {
            fontSize: ''0.75em'',
            color: "#999999"
          }
        },
        opposite: true,
        min: 0,
        labels: {
          style: {
            fontSize: ''0.7em'',
            color: "#999999"
          }
        },
        gridLineWidth: 0,
        minorGridLineWidth: 0,
        lineWidth: 1
      }],
      legend: {
        layout: ''vertical'',
