    },
    {
      indicator: "Use per area of cropland (kg/ha)",
      name: "Use per area of cropland", 
      unit: " kg/ha"
    }
  ];
  const colors = [
    "#4f9e45",
    "#efb960",
    "#cc7c4b",
    "#077cc0",
    "#bcd231"
  ];

  /**
   * Queries to retrieve data from Superset
   */
  const queryContext = {
    datasource: {
      id: 20,
      type: "table"
    },
    force: false,
    queries: [{
      time_range: "No filter",
      filters: [
        {
          col: "iso3",
          op: "==",
          val: `${country}`
        }
      ],
      extras: {
        time_grain_sqla: "P1D",
        having: "",
        having_druid: []
      },
      applied_time_extras: {},
