    async function apiSupersetGet(apiBaseUrl, queryContext) {
      const response = await fetch(`${apiBaseUrl}/v1/chart/data`, {
        method: ''POST'',
        headers: {
          ''accept'': ''application/json'',
          ''Content-Type'': ''application/json''
        },
        body: JSON.stringify(queryContext)
      });
      const json = await response.json();
      const data = json.result[0].data;
      return data;
    }
  
    function generateSerie(data, config) {
      // format data for Highcharts
      data.forEach(d => d.year = new Date(d.date_start).getFullYear());
      const serie = data.map(e => [e.year, e.indicator_value]);
      config.serie = serie;
  
      // retrieve last value
      const index_last_value = data.length - 1;
      const last_value = data[index_last_value].indicator_value;
      const last_year = data[index_last_value].year;
      config.value = formatNumber(last_value);
      config.year = last_year;
    }
  
    function generateLabel(config) {
      if (!(''label_value'' in config)) {
        config.label_value = `${config.value} ${config.unit}`;
      }
    }
  
    function generateUI(config) {
      const indicator_label = document.getElementById("indicator_label_parea");
      const indicator_value = document.getElementById("indicator_value_parea");
      const year = document.getElementById("year_parea");
      const credits = document.getElementById("credits_parea");
      indicator_label.innerText = config.indicator;
      indicator_value.innerText = config.label_value;
      year.innerText = config.year;
      credits.innerText = `Credits: ${config.credits}`;
    }
  
    // source: https://stackoverflow.com/questions/10599933/convert-long-number-into-abbreviated-string-in-javascript-with-a-special-shortn
    function formatNumber(number) {
      if (number < 1e3) return number.toFixed(1);
      if (number >= 1e3 && number < 1e6) return +(number / 1e3).toFixed(1) + "K";
      if (number >= 1e6 && number < 1e9) return +(number / 1e6).toFixed(1) + "M";
      if (number >= 1e9 && number < 1e12) return +(number / 1e9).toFixed(1) + "B";
      if (number >= 1e12) return +(n / 1e12).toFixed(1) + "T";
    }
  })();

