              lineWidth: 0,
              tickLength: 0
        },
        yAxis: {
            title: {
                text: undefined
              },
              labels: {
                style: {
                  fontSize: ''0.7em'',
                  color: "#999999"
                }
              },
              gridLineWidth: 0,
              minorGridLineWidth: 0,
              lineWidth: 1
        },
        credits: {
            text: ''Credits: FAO'',
            href: '''',
            style: {
              fontSize: "0.7em"
            },
            position:
            {
              align: "left",
              verticalAlign: "bottom",
              x: 10,
              y: -10
            }
          },
        tooltip: {
          formatter: function () {
            return `${this.x}: <b>${Highcharts.numberFormat(this.y, config.decimal)} ${config.unit}</b>`;
          }
        },
        series: [{
          name: config.indicator_label,
          data: config.serie,
