    const response = await fetch(`${apiBaseUrl}/v1/chart/data`, {
      method: ''POST'',
      headers: {
        ''accept'': ''application/json'',
        ''Content-Type'': ''application/json''
      },
      body: JSON.stringify(queryContext)
    });
    const data = await response.json();
    return data.result[0].data;
  }

  function initSeriesTrends(data) {
    let sortedData = data.sort((a, b) => a.date_start - b.date_start);

    let ghg = [],
      gdp = [],
      pop = [],
      years = [];

    sortedData.forEach(d => {
      ghg.push(d.indicator_value);
      gdp.push(d.gdp);
      pop.push(d.pop);

      let date = new Date(d.date_start);
      let year = date.getUTCFullYear();
      years.push(year);
    });

    const isNotNull = (element) => (element) != null;

    const ghgFirstValueIndex = ghg.findIndex(isNotNull);
    const gdpFirstValueIndex = gdp.findIndex(isNotNull);
    const popFirstValueIndex = pop.findIndex(isNotNull);

    let series = {
      ghg: yearlyIncrease(ghg, ghgFirstValueIndex),
      gdp: yearlyIncrease(gdp, gdpFirstValueIndex),
      pop: yearlyIncrease(pop, popFirstValueIndex),
      years: years
    };
    return series;
  }

  function yearlyIncrease(data, firstValue) {
    let length = data.length;
    let yearlyIncrease = [];

    for (let i = 0; i < length; i++) {
      if (i < firstValue) {
        yearlyIncrease.push(null);
      } else {
        if (data[i]) {
          let value = (((data[i] - data[firstValue]) / data[firstValue]) * 100);
          yearlyIncrease.push(value);
        } else {
