          },
        plotOptions: {
          column: {
            stacking: "normal"
          }
        },
        tooltip: {
         shared: true,
          valueDecimals: 0,
          valueSuffix: '' people'',
          useHTML: true
        },
        credits: {
            text: ''Credits: Climatic Research Unit (University of East Anglia) and Met Office'',
            href: '''',
            style: {
              fontSize: "0.7em"
            },
            position:
            {
              align: "left",
