  const colors = [
    "#4f9e45",
    "#efb960",
    "#cc7c4b",
    "#077cc0",
    "#bcd231"
  ];

  /**
   * Queries to retrieve data from Superset
   */
  const queryContextTrends = {
    datasource: {
      id: 13,
      type: "table"
    },
    force: false,
    queries: [{
      time_range: "No filter",
      filters: [{
        col: "indicator_uid",
