      const indicator_label = document.getElementById("indicator_label_forest");
      const indicator_value = document.getElementById("indicator_value_forest");
      const footer = document.getElementById("footer_forest");
      indicator_label.innerText = config.indicator;
      indicator_value.innerText = config.label_value;
      footer.innerText = config.footer;
    }
  
    function generateLineChart(container, config, colors) {
      const options = {
        chart: {
          type: ''area'',
