  function initSeriesTrends(data) {
    let sortedData = data.sort((a, b) => a.date_start - b.date_start);

    let ghg = [],
      gdp = [],
      pop = [],
      years = [];

    sortedData.forEach(d => {
      ghg.push(d.indicator_value);
      gdp.push(d.gdp);
      pop.push(d.pop);

      let date = new Date(d.date_start);
      let year = date.getUTCFullYear();
      years.push(year);
    });

    const isNotNull = (element) => (element) != null;

    const ghgFirstValueIndex = ghg.findIndex(isNotNull);
    const gdpFirstValueIndex = gdp.findIndex(isNotNull);
    const popFirstValueIndex = pop.findIndex(isNotNull);

