      orderby: [],
      row_limit: 10000,
      timeseries_limit: 0,
      url_params: {}
    }],
    result_format: "json",
    result_type: "full"
  };

  /**
   * Fetch all data
   */
  const data = await fetchData(apiBaseUrl, queryContext);
  const yearMinMax = findMinMax(data, "year");
  const years = generateSequence(yearMinMax.min, yearMinMax.max);
  const series = indicators.map(i => {
    const data_indicator = data.filter(d => d.indicator == i.indicator);
    const serie = years.map(y => hasKeyValue(data_indicator, "year", y) ? getKeyYear(data_indicator, y, "value") : null);
    return {
      name: i.name,
      data: serie,
      unit: i.unit
    };
  });
  initChart(chart_container, years, series, colors);

  /*
