          metrics: [],
          order_desc: true,
          orderby: [
            [
              "date_start",
              true
            ]
          ],
          row_limit: 50000,
          timeseries_limit: 0,
          url_params: {}
        }],
        result_format: "json",
        result_type: "full"
      };
