            fontFamily: ''Montserrat, sans-serif''
          }
        },
        colors: colors,
        title: {
          text: ""
        },
        xAxis: {
          categories: categories,
          labels: {
            style: {
              fontSize: ''0.7em'',
              color: "#999999"
            }
          },
          tickPositions: [0, (categories.length - 1)],
          gridLineWidth: 0,
          minorGridLineWidth: 0,
          lineWidth: 0
        },
        yAxis: {
            title: {
                text: undefined
              },
              labels: {
                style: {
                  fontSize: ''0.7em'',
                  color: "#999999"
                }
              },
              gridLineWidth: 0,
              minorGridLineWidth: 0,
              lineWidth: 1
        },
        legend: {
            layout: ''vertical'',
            align: ''left'',
            verticalAlign: ''top'',
            floating: true,
            borderWidth: 0.5,
            borderRadius: 5,
            itemStyle: {
                fontSize: ''0.8em'',
                fontWeight: ''normal''
            },
            x: 45,
            y: 0
          },
        plotOptions: {
          column: {
            stacking: "normal"
          }
        },
        tooltip: {
         shared: true,
          valueDecimals: 0,
          valueSuffix: '' people'',
          useHTML: true
        },
        credits: {
            text: ''Credits: Climatic Research Unit (University of East Anglia) and Met Office'',
            href: '''',
            style: {
              fontSize: "0.7em"
            },
            position:
            {
              align: "left",
              verticalAlign: "bottom",
              x: 10,
              y: -10
            }
          },
        series: series
      });
    }
  })();

