        </div>
        <div id="chart_cont_forest" class="grow dataviz-chart"></div>
      </div>
  </div>`;
    $(this).html(html);
  
    /**
   * Parameters
   */
    const apiBaseUrl = ''https://dash.unccd.unepgrid.ch/api'';
    const country = ''[grid-dataviz:iso3cc]'';
    const colors = [''#efb960''];
  
    const config = {
      table: ''13'',
      indicator: ''Forest area'',
      indicator_uids: [''2700''],
      table_columns: [''date_start'', ''indicator_value''],
      unit: ''%'',
      unit_long: ''% land'',
      trend_years: 10,
      decimal: 2
    };
  
    const query = generateQueryContext(config, country);
    const data = await apiSupersetGet(apiBaseUrl, query);
    generateSerie(data, config);
    generateLabel(config);
    generateUI(config);
    const chart_container = document.getElementById("chart_cont_forest");
    generateLineChart(chart_container, config, colors);
  
    /**
    * Utility functions
    */
    function generateQueryContext(config, country) {
      return {
        datasource: {
          id: config.table,
          type: "table"
        },
        force: false,
        queries: [{
          time_range: "No filter",
          filters: [{
            col: "code_iso3",
            op: "==",
            val: country
          },
          {
            col: "indicator_uid",
            op: "IN",
            val: config.indicator_uids
          }],
          extras: {
            time_grain_sqla: "P1D",
            having: "",
            having_druid: []
          },
          applied_time_extras: {},
          annotation_layers: [],
          groupby: [],
          columns: config.table_columns,
          metrics: [],
          order_desc: true,
          orderby: [
            [
              "date_start",
              true
            ]
          ],
          row_limit: 50000,
          timeseries_limit: 0,
          url_params: {}
        }],
        result_format: "json",
        result_type: "full"
      };
    }
  
    async function apiSupersetGet(apiBaseUrl, queryContext) {
      const response = await fetch(`${apiBaseUrl}/v1/chart/data`, {
        method: ''POST'',
        headers: {
          ''accept'': ''application/json'',
          ''Content-Type'': ''application/json''
        },
        body: JSON.stringify(queryContext)
      });
      const json = await response.json();
      const data = json.result[0].data;
      return data;
    }
  
    function generateSerie(data, config) {
      // format data for Highcharts
      data.forEach(d => d.year = new Date(d.date_start).getFullYear());
      const serie = data.map(e => [e.year, e.indicator_value]);
      config.serie = serie;
  
      // retrieve last value
      const index_last_value = data.length - 1;
      const last_value = data[index_last_value].indicator_value;
      const last_year = data[index_last_value].year;
      config.value = formatNumber(last_value);
  
      // calculate the trend if needed
      if (config.trend_years != undefined && Number.isInteger(config.trend_years)) {
        const start_year = last_year - config.trend_years;
        const start_value = data.find(e => e.year == start_year).indicator_value;
        if (start_value == undefined && isNaN(start_value) == true) {
          config.trend_value = '''';
        } else {
          config.trend_value = (((last_value - start_value) / Math.abs(start_value)) * 100).toFixed(1);
        }
      }
    }
  
    function generateLabel(config) {
      if (!(''label_value'' in config)) {
        config.label_value = `${config.value} ${config.unit_long}`;
      }
      if (''trend_years'' in config && ''trend_value'' in config && !(''footer'' in config)) {
        config.footer = `${config.trend_value} % change over last ${config.trend_years} years`;
      }
    }
  
    function generateUI(config) {
      const indicator_label = document.getElementById("indicator_label_forest");
      const indicator_value = document.getElementById("indicator_value_forest");
      const footer = document.getElementById("footer_forest");
      indicator_label.innerText = config.indicator;
      indicator_value.innerText = config.label_value;
      footer.innerText = config.footer;
    }
  
    function generateLineChart(container, config, colors) {
      const options = {
        chart: {
          type: ''area'',
          margin: [20, 10, 45, 40],
          style: {
            fontFamily: ''Montserrat, sans-serif''
          }
        },
        colors: colors,
        title: {
          text: ''''
        },
        legend: {
          enabled: false
        },
        plotOptions: {
          area: {
            fillOpacity: 0,
            marker: {
              enabled: false
            },
            lineWidth: 2,
            states: {
              hover: {
                enabled: false
              }
            },
            threshold: null
          }
        },
        xAxis: {
            labels: {
                style: {
                  fontSize: ''0.7em'',
                  color: "#999999"
                }
              },
              gridLineWidth: 0,
              minorGridLineWidth: 0,
              lineWidth: 0,
              tickLength: 0
        },
        yAxis: {
            title: {
                text: undefined
              },
              labels: {
                style: {
                  fontSize: ''0.7em'',
                  color: "#999999"
                }
              },
              gridLineWidth: 0,
              minorGridLineWidth: 0,
              lineWidth: 1
        },
        credits: {
            text: ''Credits: FAO'',
            href: '''',
            style: {
              fontSize: "0.7em"
            },
            position:
            {
              align: "left",
              verticalAlign: "bottom",
              x: 10,
              y: -10
            }
          },
        tooltip: {
          formatter: function () {
            return `${this.x}: <b>${Highcharts.numberFormat(this.y, config.decimal)} ${config.unit}</b>`;
          }
        },
        series: [{
          name: config.indicator_label,
          data: config.serie,
          color: colors[0],
          fillColor: {
            linearGradient: {
              x1: 0,
              x2: 0,
              y1: 0,
              y2: 1
            },
            stops: [
              [0, Highcharts.color(colors[0]).setOpacity(0.5).get(''rgba'')],
              [1, Highcharts.color(colors[0]).setOpacity(0).get(''rgba'')]
            ]
          }
        }]
      };
      Highcharts.chart(container, options);
    }
  
    // source: https://stackoverflow.com/questions/10599933/convert-long-number-into-abbreviated-string-in-javascript-with-a-special-shortn
    function formatNumber(number) {
      if (number < 1e3) return number.toFixed(1);
      if (number >= 1e3 && number < 1e6) return +(number / 1e3).toFixed(1) + "K";
      if (number >= 1e6 && number < 1e9) return +(number / 1e6).toFixed(1) + "M";
