     */
    const chart_container = document.getElementById(container_id);
    const apiBaseUrl = "https://dash.unccd.unepgrid.ch/api";
    const country = "[grid-dataviz:iso3cc]";
    const indicators = [
      "Wet mass movement",
      "Drought",
      "Wildfire",
      "Flood"
    ]
    const colors = [
      "#4f9e45",
      "#efb960",
      "#cc7c4b",
      "#077cc0",
      "#bcd231"
    ];
  
    /**
     * Queries to retrieve data from Superset
     */
    const queryContext = {
      datasource: {
        id: 15,
        type: "table"
      },
      force: false,
      queries: [{
        time_range: "No filter",
        filters: [
          {
            col: "iso3",
            op: "==",
            val: `${country}`
          }
        ],
        extras: {
          time_grain_sqla: "P1D",
          having: "",
          having_druid: []
        },
        applied_time_extras: {},
        annotation_layers: [],
        groupby: [],
        columns: [
          "indicator",
          "value",
          "year"
        ],
        metrics: [],
        order_desc: true,
        orderby: [],
        row_limit: 10000,
        timeseries_limit: 0,
        url_params: {}
      }],
      result_format: "json",
      result_type: "full"
    };
  
    /**
     * Fetch all data
     */
    const data = await fetchData(apiBaseUrl, queryContext);
    const yearMinMax = findMinMax(data, "year");
    const years = generateSequence(yearMinMax.min, yearMinMax.max);
    const series = indicators.map(i => {
      const data_indicator = data.filter(d => d.indicator == i);
      const serie = years.map(y => hasKeyValue(data_indicator, "year", y) ? getKeyYear(data_indicator, y, "value") : null);
      return {
        name: i,
        data: serie
      };
    })
    initChart(chart_container, years, series, colors);
  
    /*
     * Utility functions
     */
    async function fetchData(apiBaseUrl, queryContext) {
      const response = await fetch(`${apiBaseUrl}/v1/chart/data`, {
        method: "POST",
        headers: {
          "accept": "application/json",
          "Content-Type": "application/json"
        },
        body: JSON.stringify(queryContext)
      });
      const data = await response.json();
      return data.result[0].data;
    }
  
    function findMinMax(arr, key) {
      return arr.reduce((result, obj) => {
        result.min = Math.min(result.min, obj[key]);
        result.max = Math.max(result.max, obj[key]);
        return result;
      }, { min: Infinity, max: -Infinity });
    };
  
    function generateSequence(min, max) {
      const sequence = [];
      for (let i = min; i <= max; i++) {
        sequence.push(i);
      }
      return sequence;
    }
  
    function hasKeyValue(arr, key, value) {
      return arr.some(function (obj) {
        return obj.hasOwnProperty(key) && obj[key] === value;
      });
    }
  
    function getKeyYear(arr, year, key) {
      return arr.find(obj => obj.year == year)[key]
    }
  
    function initChart(chart_container, categories, series, colors) {
      Highcharts.chart(chart_container, {
        chart: {
          type: "column",
          margin: [10, 10, 45, 40],
          style: {
            fontFamily: ''Montserrat, sans-serif''
          }
        },
        colors: colors,
        title: {
          text: ""
        },
        xAxis: {
          categories: categories,
          labels: {
            style: {
              fontSize: ''0.7em'',
              color: "#999999"
            }
          },
          tickPositions: [0, (categories.length - 1)],
          gridLineWidth: 0,
          minorGridLineWidth: 0,
          lineWidth: 0
        },
        yAxis: {
            title: {
                text: undefined
              },
              labels: {
                style: {
                  fontSize: ''0.7em'',
                  color: "#999999"
                }
              },
              gridLineWidth: 0,
              minorGridLineWidth: 0,
              lineWidth: 1
        },
        legend: {
            layout: ''vertical'',
            align: ''left'',
            verticalAlign: ''top'',
            floating: true,
            borderWidth: 0.5,
            borderRadius: 5,
            itemStyle: {
                fontSize: ''0.8em'',
                fontWeight: ''normal''
            },
            x: 45,
            y: 0
          },
        plotOptions: {
          column: {
            stacking: "normal"
          }
        },
        tooltip: {
         shared: true,
          valueDecimals: 0,
          valueSuffix: '' people'',
          useHTML: true
        },
        credits: {
            text: ''Credits: Climatic Research Unit (University of East Anglia) and Met Office'',
            href: '''',
            style: {
              fontSize: "0.7em"
            },
            position:
            {
              align: "left",
              verticalAlign: "bottom",
              x: 10,
              y: -10
            }
          },
        series: series
      });
    }
  })();

