 */
var Manager = mxsdk.Manager;
const country = ''[grid-dataviz:iso3cc]'';

const options = [{
  text: ''Mapbox satellite'',
  value: ''MX-9D1UE-26V0W-S437Y''
},{
  text: ''Population - 2015'',
  value: ''MX-5DI5D-BR0SF-JO4HT''
},
{
  text: ''Emissions of CO2 -2018'',
  value: ''MX-GR46V-U5X24-BWD1L''
}, {
  text: ''Tree cover fraction - 2019'',
  value: ''MX-F05Y5-03HZC-Q8VMW''
}];

/*
 * Setup drop-down llist
 */
const selectView = document.getElementById(''country-viz-cnm-selectView'');

options.forEach((o, i) => {
  selectView[i] = new Option(o.text, o.value);
});
selectView.addEventListener(''change'', updateView);

/*
 * Setup MapX SDK
 */
const m = new mxsdk.Manager({
  container: document.getElementById(''mapx''),
  url: {
    host: ''app.mapx.org'',
    protocol: ''https'',
    port: 443
  },
  static: true,
  verbose: false,
  params: {
    closePanels: true
  }
});

m.on(''ready'', async () => {
  await m.ask(''set_immersive_mode'', {
    toggle: true
  });
  await m.ask(''common_loc_fit_bbox'', {
    code: country
  });
  selectView.classList.remove(''hidden'');
  updateView();
});

/*
 * Utilitiy functions
 */
async function updateView() {
  await removeView();
  await addView();
}

async function addView() {
  const idView = selectView.value;
  await m.ask(''view_add'', {
    idView: idView
  });
}


async function removeView() {
  const idViews = options.map(o => o.value);
  for (idView of idViews) {
    await m.ask(''view_remove'', {
      idView: idView
    });
  }
}

