      // format data for Highcharts
      data.forEach(d => d.year = new Date(d.date_start).getFullYear());
      const serie = data.map(e => [e.year, e.indicator_value]);
      config.serie = serie;
  
      // retrieve last value
      const index_last_value = data.length - 1;
      const last_value = data[index_last_value].indicator_value;
      const last_year = data[index_last_value].year;
      config.value = formatNumber(last_value);
      config.year = last_year;
    }
  
    function generateLabel(config) {
      if (!(''label_value'' in config)) {
        config.label_value = `${config.value} ${config.unit}`;
      }
    }
  
    function generateUI(config) {
      const indicator_label = document.getElementById("indicator_label_parea");
      const indicator_value = document.getElementById("indicator_value_parea");
      const year = document.getElementById("year_parea");
      const credits = document.getElementById("credits_parea");
