              minorGridLineWidth: 0,
              lineWidth: 1
        },
        legend: {
            layout: ''vertical'',
            align: ''left'',
            verticalAlign: ''top'',
            floating: true,
            borderWidth: 0.5,
            borderRadius: 5,
            itemStyle: {
                fontSize: ''0.8em'',
                fontWeight: ''normal''
            },
            x: 45,
